from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,sys,subprocess
H=Path(__file__).resolve().parent
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
freeze=json.loads((H/'analysis-freeze.json').read_text());assert all(sha(H/k)==v for k,v in freeze['source_hashes'].items())
for script in ['run_analysis.py','check_normal.py']:
    subprocess.run([sys.executable,str(H/script)],check=True)
d=json.loads((H/'diagnostics.json').read_text());v=d['results']['sized'];normal=json.loads((H/'normal-diagnostic.json').read_text())['results'];old=json.loads((H.parent/'softplay_capacity_20260910/diagnostics.json').read_text())['results']['b0_capacity'];replay=json.loads((H/'sized/intervention-replay-audit.json').read_text());passed=v['realism_gate_passed'] and normal['sized']['passes_ceiling'];p=json.loads((H/'study-plan.json').read_text());assert all(sha(H.parents[1]/n)==v for n,v in p['protected'].items())
result={'at':datetime.now(timezone.utc).isoformat(),'passes_initial_pilot':passed,'soft_source_auc':v['source_auc'],'control_soft_source_auc':old['source_auc'],'normal_source_auc':normal['sized']['source_auc'],'control_normal_source_auc':normal['control']['source_auc'],'calling':v['action_summary']['preflop']['equal_pair_mean_fold_check_call_raise'][2],'call_strength':v['conditional']['preflop_calls']['own_strength'],'supported_pairs':v['supported_pairs'],'replayed_hands':replay['hands'],'verified_changes':replay['counterfactual_action_changes_verified'],'no_new_utility_score':True,'protected_submissions_unchanged':True,'next_step':'Freeze broader unchanged-policy development and fresh-seed confirmation before any utility study.' if passed else 'Keep failed sizing pilot. Inspect training-only realized bet sizes and pressure; do not run utility or treat requested-size prediction as sufficient.'}
(H/'summary.json').write_text(json.dumps(result,indent=2));lines=['# Conditional bet-size simulation pilot','',('PASS' if passed else 'FAIL')+' under the predeclared initial-pilot rules.','',f"One paired32-pool population produces96,000 hands. Soft-play source AUC: {old['source_auc']:.6f} -> {v['source_auc']:.6f}. Confirmed-none source AUC: {normal['control']['source_auc']:.6f} -> {normal['sized']['source_auc']:.6f}. Calling {result['calling']:.6f}, call strength {result['call_strength']:.6f}, supported targets {result['supported_pairs']}. All legal/accounting/causal checks pass; {result['verified_changes']} changed actions independently replayed.",'','The training-only raise-size probe improved pinball loss12.47% across all4 inner policy partitions;80% interval coverage rose56.30% ->89.69%, with excessive preflop coverage. The simulator interpolates these conditional quantiles with fixed tail extrapolation and unchanged legal clipping. Requested-size prediction and actual full-history realism are distinct checks.','',result['next_step'],'','This is one development replay, not independent real-world confirmation. No new detector fit, outer-held score, VM or submission. Prior capacity utility failure remains unchanged.',''];(H/'RESULTS.md').write_text('\n'.join(lines),encoding='utf-8');print(json.dumps(result,indent=2))
